 }

+impl IntoGpui for PixelSetting {
+    type Output = Pixels;
+
+    fn into_gpui(self) -> Self::Output {
+        px(self.0)
+    }
+}
+
 impl IntoGpui for FontFamilyName {
     type Output = SharedString;

